import products from './products.json' with { type: 'json' };

const TOOL_NAME = 'inventory_search';

const inputSchema = {
  type: 'object',
  properties: {
    query: { type: 'string' },
    limit: { type: 'integer', minimum: 1, maximum: 10 },
  },
  required: ['query'],
  additionalProperties: false,
};

function validateArgs(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }
  if (typeof args.query !== 'string') {
    throw new Error('Invalid arguments: query must be a string');
  }
  if (args.limit !== undefined) {
    if (!Number.isInteger(args.limit) || args.limit < 1 || args.limit > 10) {
      throw new Error('Invalid arguments: limit must be an integer between 1 and 10');
    }
  }
}

export async function listTools() {
  return [
    {
      name: TOOL_NAME,
      description: 'Search inventory products by name (case-insensitive).',
      inputSchema,
    },
  ];
}

export async function callTool(name, args) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }
  validateArgs(args);
  const q = args.query.toLowerCase();
  const limit = args.limit ?? 10;
  const matches = products
    .filter((p) => typeof p.name === 'string' && p.name.toLowerCase().includes(q))
    .slice(0, limit);
  const text = matches.length
    ? matches.map((p) => `${p.id}: ${p.name}`).join('\n')
    : 'No matching products';
  return { content: [{ type: 'text', text }] };
}

